```python
def longest_common_subsequence(str1, str2):
    # Initialize a 2D DP table with (str1_length + 1, str2_length + 1)
    dp_table = [[0] * (len(str2) + 1) for _ in range(len(str1) + 1)]

    # Fill the DP table
    for i in range(1, len(str1) + 1):
        for j in range(1, len(str2) + 1):
            if str1[i - 1] == str2[j - 1]:
                dp_table[i][j] = dp_table[i - 1][j - 1] + 1
            else:
                dp_table[i][j] = max(dp_table[i - 1][j], dp_table[i][j - 1])

    # The value at dp_table[len(str1)][len(str2)] will be the length of the LCS
    return dp_table[len(str1)][len(str2)]

